INSERT INTO `zz_group_module` VALUES (1,2,3,'Mostra al tecnico solo le sue attività programmate e assegnate','in_interventi.id IN (SELECT idintervento FROM in_interventi_tecnici WHERE idintervento=in_interventi.id AND idtecnico=|id_anagrafica| UNION SELECT id_intervento FROM in_interventi_tecnici_assegnati WHERE id_intervento=in_interventi.id AND id_tecnico=|id_anagrafica|)','WHR',1,1,'2026-02-18 19:20:36','2026-02-18 19:22:35'),(2,2,2,'Mostra ai tecnici solo le anagrafiche in cui sono coinvolti con delle attività',' an_anagrafiche.idanagrafica IN (SELECT idanagrafica FROM in_interventi_tecnici INNER JOIN in_interventi ON in_interventi_tecnici.idintervento=in_interventi.id WHERE in_interventi.idanagrafica=an_anagrafiche.idanagrafica AND idtecnico=|id_anagrafica|)','WHR',0,1,'2026-02-18 19:20:36','2026-02-18 19:20:50'),(3,3,2,'Mostra agli agenti solo le anagrafiche di cui sono agenti',' an_anagrafiche.idagente=|id_anagrafica|','WHR',1,1,'2026-02-18 19:20:36','2026-02-18 19:20:50'),(4,4,2,'Mostra ai clienti solo la propria anagrafica',' an_anagrafiche.idanagrafica=|id_anagrafica|','WHR',1,1,'2026-02-18 19:20:36','2026-02-18 19:20:50'),(5,4,3,'Mostra al cliente solo le attività in cui è impostato come \'Cliente\'',' in_interventi.idanagrafica=|id_anagrafica|','WHR',1,1,'2026-02-18 19:20:36','2026-02-18 19:22:35'),(6,4,14,'Mostra ai clienti solo le proprie fatture',' co_documenti.idanagrafica=|id_anagrafica|','WHR',1,1,'2026-02-18 19:20:36','2026-02-18 19:20:50'),(7,3,16,'Mostra agli agenti solo la prima nota delle anagrafiche di cui sono agenti',' idagente=|id_anagrafica|','WHR',1,1,'2026-02-18 19:20:36','2026-02-18 19:20:50'),(8,4,30,'Mostra ai clienti solo i propri impianti',' my_impianti.idanagrafica=|id_anagrafica|','WHR',1,1,'2026-02-18 19:20:36','2026-02-18 19:20:50'),(9,4,26,'Mostra ddt di vendita ai clienti coinvolti','dt_ddt.idanagrafica=|id_anagrafica|','WHR',0,1,'2026-02-18 19:20:44','2026-02-18 19:20:48'),(10,4,24,'Mostra ordini cliente ai clienti coinvolti','or_ordini.idanagrafica=|id_anagrafica|','WHR',0,1,'2026-02-18 19:20:44','2026-02-18 19:20:48'),(11,4,14,'Mostra ai clienti solo le proprie fatture','co_documenti.idanagrafica=|id_anagrafica|','WHR',0,1,'2026-02-18 19:20:44','2026-02-18 19:20:50'),(12,2,3,'Mostra al tecnico solo le attività a cui è stato assegnato','in_interventi.id IN (SELECT id_intervento FROM in_interventi_tecnici_assegnati WHERE id_intervento=in_interventi.id AND id_tecnico=|id_anagrafica|)','WHR',0,1,'2026-02-18 19:22:08','2026-02-18 19:22:35'),(13,4,31,'Mostra i contratti ai clienti coinvolti','co_contratti.idanagrafica=|id_anagrafica|','WHR',1,1,'2026-02-18 19:22:08','2026-02-18 19:22:08'),(14,2,30,'Mostra impianti ai tecnici assegnati','my_impianti.idtecnico=|id_anagrafica|','WHR',0,1,'2026-02-18 19:22:17','2026-02-18 19:22:17'),(15,4,13,'Mostra agli agenti solo le anagrafiche di cui sono agenti','co_preventivi.idanagrafica=|id_anagrafica|','WHR',1,0,'2026-02-18 19:22:32','2026-02-18 19:22:35'),(16,3,13,'Mostra agli agenti solo i preventivi dei clienti dei quali si è agenti','an_anagrafiche.idagente=|id_anagrafica|','WHR',1,0,'2026-02-18 19:22:35','2026-02-18 19:22:35'),(17,3,13,'Mostra agli agenti solo i preventivi di cui sono agenti','co_preventivi.idagente=|id_anagrafica|','WHR',1,0,'2026-02-18 19:22:35','2026-02-18 19:22:35'),(18,4,3,'Mostra al cliente solo le attività in cui è impostato come \'Per conto di\'','in_interventi.idclientefinale=|id_anagrafica|','WHR',0,1,'2026-02-18 19:22:35','2026-02-18 19:22:35'),(19,4,3,'Mostra al cliente tutte le attività in cui è coinvolto','(in_interventi.idanagrafica=|id_anagrafica| OR in_interventi.idclientefinale=|id_anagrafica|)','WHR',0,1,'2026-02-18 19:22:35','2026-02-18 19:22:35');
