tomezzi','automezzi','SELECT |select| FROM an_sedi INNER JOIN zz_settings ON (zz_settings.valore=an_sedi.idanagrafica AND zz_settings.nome=\'Azienda predefinita\' ) WHERE 1=1 AND an_sedi.is_automezzo=1 HAVING 2=2 ORDER BY nomesede ASC','','fa fa-circle-o','2.9.8','2.9.8',100,20,1,1,'2026-02-18 19:23:16','2026-02-18 19:25:27',0,0),(93,'Accesso con OAuth','oauth','oauth','SELECT |select| FROM zz_oauth2 WHERE 1=1 AND is_login=1 HAVING 2=2','','fa fa-circle-o','2.9.8','2.9.8',100,103,1,1,'2026-02-18 19:23:21','2026-02-18 19:25:27',0,0),(94,'Adattatori di archiviazione','adattatori_archiviazione','adattatori_archiviazione','\nSELECT\n    |select| \nFROM \n    `zz_storage_adapters` \nWHERE \n    1=1 AND `deleted_at` IS NULL\nHAVING \n    2=2','','fa fa-folder','2.9.8','2.9.8',2,36,1,1,'2026-02-18 19:23:37','2026-02-18 19:25:27',0,0),(96,'Tags','tags','tags','SELECT |select| FROM `in_tags` WHERE 1=1 HAVING 2=2','','fa fa-circle-o','2.9.8','2.9.8',2,40,1,1,'2026-02-18 19:23:59','2026-02-18 19:25:27',1,0),(97,'Marche','marche','marchi','SELECT\n    |select|\nFROM\n    `zz_marche`\nWHERE\n    1=1\n    AND\n    `parent` IS NULL\nHAVING\n    2=2\nORDER BY\n    `name`','','fa fa-circle-o','2.9.8','2.9.8',7,40,1,1,'2026-02-18 19:24:16','2026-02-18 19:25:27',1,1),(98,'Stati DDT','stati_ddt','stati_ddt','SELECT |select| FROM `dt_statiddt` LEFT JOIN `dt_statiddt_lang` ON (`dt_statiddt`.`id` = `dt_statiddt_lang`.`id_record` AND `dt_statiddt_lang`.|lang|) WHERE 1=1 AND `deleted_at` IS NULL HAVING 2=2','','fa fa-circle-o','2.9.8','2.9.8',7,40,1,1,'2026-02-18 19:24:16','2026-02-18 19:25:27',1,1),(99,'Categorie contratti','categorie_contratti','categorie_contratti','\r\nSELECT\r\n |select|\r\nFROM \r\n `co_categorie_contratti`\r\n    LEFT JOIN `co_categorie_contratti_lang` ON (`co_categorie_contratti`.`id` = `co_categorie_contratti_lang`.`id_record` AND `co_categorie_contratti_lang`.|lang|)\r\nWHERE \r\n    1=1 AND `parent` IS NULL \r\nHAVING \r\n    2=2','','fa fa-circle-o','2.9.8','2.9.8',1,40,1,1,'2026-02-18 19:24:16','2026-02-18 19:25:27',0,0),(100,'Descrizioni predefinite','descrizioni_predefinite','','SELECT |select| FROM `zz_default_description` WHERE 1=1 HAVING 2=2','','fa fa-circle-o','2.9.8','2.9.8',8,40,1,1,'2026-02-18 19:24:38','2026-02-18 19:25:27',1,1),(101,'Categorie file','categorie_files','','SELECT |select| FROM `zz_files_categories` WHERE 1=1 AND `deleted_at` IS NULL HAVING 2=2','','fa fa-circle-o','2.9.8','2.9.8',8,40,1,1,'2026-02-18 19:24:40','2026-02-18 19:25:27',1,1),(102,'Accesso con Token/OTP','otp_tokens','','SELECT |select| FROM `zz_otp_tokens` WHERE 1=1 HAVING 2=2','','fa fa-link','2.9.8','2.9.8',1,103,1,1,'2026-02-18 19:24:49','2026-02-18 19:25:27',0,0),(103,'Gestione accessi','','','menu','','fa fa-key','2.9.8','2.9.8',1,36,1,1,'2026-02-18 19:24:49','2026-02-18 19:25:27',0,0),(104,'Log eventi','log_task','','SELECT |select|\nFROM (\n    SELECT\n        zz_tasks_logs.id,\n        name,\n        zz_tasks_logs.level,\n        zz_tasks_logs.message,\n        IF(LEVEL = \'info\', \'#dff0d8\', IF(LEVEL = \'error\', \'#f2dede\', \'#fcf8e3\')) AS \'_bg_\',\n        IF(CHAR_LENGTH(CONTEXT) > 200,\n           CONCAT(SUBSTRING(CONTEXT, 1, 200), \'<a title=\"\', REPLACE(CONTEXT, \'\">\', \'[...]\'), \'</a>\'),\n           CONTEXT) AS \'Contesto\',\n        CONTEXT AS \'contesto_esteso\',\n        zz_tasks_logs.created_at AS \'Data inizio\',\n        zz_tasks_logs.updated_at AS \'Data fine\',\n        CONCAT(TIMESTAMPDIFF(SECOND, zz_tasks_logs.created_at, zz_tasks_logs.updated_at), \' secondi\') AS \'Eseguito in\'\n    FROM `zz_tasks_logs`\n    INNER JOIN `zz_tasks` ON `zz_tasks`.`id`=`zz_tasks_logs`.`id_task`\n\n    UNION ALL\n\n    SELECT\n        zz_api_log.id,\n        NAME,\n        zz_api_log.level,\n        zz_api_log.message,\n        IF(LEVEL = \'info\', \'#dff0d8\', IF(LEVEL = \'error\', \'#f2dede\', \'#fcf8e3\')) AS \'_bg_\',\n        IF(CHAR_LENGTH(CONTEXT) > 200,\n           CONCAT(SUBSTRING(CONTEXT, 1, 200), \'<a title=\"\', REPLACE(CONTEXT, \'\">\',\'[...]\'), \'</a>\'),\n           CONTEXT) AS \'Contesto\',\n        CONTEXT AS \'contesto_esteso\',\n        zz_api_log.created_at AS \'Data inizio\',\n        zz_api_log.updated_at AS \'Data fine\',\n        CONCAT(TIMESTAMPDIFF(SECOND, zz_api_log.created_at, zz_api_log.updated_at), \' secondi\') AS \'Eseguito in\'\n    FROM `zz_api_log`\n) AS dati\n    WHERE 1=1\n    HAVING 2=2\nORDER BY `Data inizio` DESC','','fa fa-calendar','2.9.8','2.9.8',5,91,1,1,'2026-02-18 19:24:49','2026-02-18 19:25:27',0,0),(105,'Ammortamenti / Cespiti','ammortamenti','','SELECT |select| FROM `co_righe_documenti` LEFT JOIN `co_righe_ammortamenti` ON `co_righe_ammortamenti`.`id_riga` = `co_righe_documenti`.`id` INNER JOIN `co_documenti` ON `co_documenti`.`id` = `co_righe_documenti`.`iddocumento` WHERE 1=1 AND `is_cespite` = 1 HAVING 2=2','','fa fa-circle-o','2.9.8','2.9.8',8,12,1,1,'2026-02-18 19:24:50','2026-02-18 19:25:27',1,1),(106,'Statistiche vendita','statistiche_articoli','','SELECT\n    |select|\nFROM\n    `co_documenti`\n    INNER JOIN `co_statidocumento` ON `co_statidocumento`.`id` = `co_documenti`.`idstatodocumento`\n    INNER JOIN `co_tipidocumento` ON `co_documenti`.`idtipodocumento` = `co_tipidocumento`.`id`\n    LEFT JOIN `co_statidocumento_lang` ON (`co_statidocumento`.`id` = `co_statidocumento_lang`.`id_record` AND `co_statidocumento_lang`. |lang|)\n    INNER JOIN `co_righe_documenti` ON `co_righe_documenti`.`iddocumento` = `co_documenti`.`id`\n    INNER JOIN `mg_articoli` ON `mg_articoli`.`id` = `co_righe_documenti`.`idarticolo`\n    LEFT JOIN `mg_articoli_lang` ON (`mg_articoli`.`id` = `mg_articoli_lang`.`id_record` AND `mg_articoli_lang`. |lang|)\n    LEFT JOIN (\n        SELECT\n            SUM(IF(`co_tipidocumento`.`reversed`=1, -`co_righe_documenti`.`qta`, `co_righe_documenti`.`qta`)) AS totale_qta_generale\n        FROM\n            `co_documenti`\n            INNER JOIN `co_tipidocumento` ON `co_documenti`.`idtipodocumento` = `co_tipidocumento`.`id`\n            INNER JOIN `co_righe_documenti` ON `co_righe_documenti`.`iddocumento` = `co_documenti`.`id`\n            INNER JOIN `mg_articoli` ON `mg_articoli`.`id` = `co_righe_documenti`.`idarticolo`\n            INNER JOIN `co_statidocumento` ON `co_statidocumento`.`id` = `co_documenti`.`idstatodocumento`\n            LEFT JOIN `co_statidocumento_lang` ON (`co_statidocumento`.`id` = `co_statidocumento_lang`.`id_record` AND `co_statidocumento_lang`.`id_lang` = |lang|)\n        WHERE\n            `co_tipidocumento`.`dir` = \'entrata\'\n            AND (`co_statidocumento_lang`.`title` = \'Pagato\' OR `co_statidocumento_lang`.`title` = \'Parzialmente pagato\' OR `co_statidocumento_lang`.`title` = \'Emessa\')\n    ) AS `totali_generali` ON 1=1\nWHERE\n    1=1\n    AND `co_tipidocumento`.`dir` = \'entrata\'\n    AND (`co_statidocumento_lang`.`title` = \'Pagato\' OR `co_statidocumento_lang`.`title` = \'Parzialmente pagato\' OR `co_statidocumento_lang`.`title` = \'Emessa\')\nGROUP BY\n    `co_righe_documenti`.`idarticolo`, `mg_articoli_lang`.`title`\nHAVING\n    2=2\nORDER BY\n    SUM(IF(`co_tipidocumento`.`reversed`=1, -`co_righe_documenti`.`qta`, `co_righe_documenti`.`qta`)) DESC','','fa fa-circle-o','2.9.8','2.9.8',1,21,1,1,'2026-02-18 19:24:56','2026-02-18 19:25:27',0,0);
