INSERT INTO `zz_settings` VALUES (2,'Azienda predefinita','1','query=SELECT `an_anagrafiche`.`idanagrafica` AS id, `ragione_sociale` AS descrizione FROM `an_anagrafiche` INNER JOIN `an_tipianagrafiche_anagrafiche` ON `an_anagrafiche`.`idanagrafica` = `an_tipianagrafiche_anagrafiche`.`idanagrafica` WHERE `idtipoanagrafica` = (SELECT `an_tipianagrafiche`.`id` FROM `an_tipianagrafiche` LEFT JOIN `an_tipianagrafiche_lang` ON(`an_tipianagrafiche`.`id` = `an_tipianagrafiche_lang`.`id_record`) WHERE `title` = \'Azienda\') AND `deleted_at` IS NULL',1,'Generali','2026-02-18 19:20:36','2026-02-18 20:26:52',1,0),(6,'Iva predefinita','171','query=SELECT `co_iva`.`id`, `name` AS text FROM `co_iva` LEFT JOIN `co_iva_lang` ON (`co_iva_lang`.`id_record` = `co_iva`.`id` AND `co_iva_lang`.`id_lang` = (SELECT `valore` FROM `zz_settings` WHERE `nome` = \"Lingua\"))',1,'Fatturazione','2026-02-18 19:20:36','2026-02-18 19:23:36',NULL,0),(7,'Tipo di pagamento predefinito','82','query=SELECT `co_pagamenti`.`id`, `name` AS descrizione FROM `co_pagamenti` LEFT JOIN `co_pagamenti_lang` ON (`co_pagamenti_lang`.`id_record` = `co_pagamenti`.`id` AND `co_pagamenti_lang`.`id_lang` = (SELECT `valore` FROM `zz_settings` WHERE `nome` = \"Lingua\"))',1,'Fatturazione','2026-02-18 19:20:36','2026-02-18 19:23:36',NULL,0),(8,'Ritenuta d\'acconto predefinita','2','query=SELECT id, descrizione FROM `co_ritenutaacconto` ORDER BY descrizione ASC',1,'Fatturazione','2026-02-18 19:20:36','2026-02-18 20:26:53',NULL,0),(9,'Cassa previdenziale predefinita','','query=SELECT id, descrizione FROM `co_rivalse` ORDER BY descrizione ASC',1,'Fatturazione','2026-02-18 19:20:36','2026-02-18 19:22:22',NULL,0),(10,'Importo marca da bollo','2','decimal',1,'Fatturazione','2026-02-18 19:20:36','2026-02-18 19:21:06',NULL,0),(11,'Soglia minima per l\'applicazione della marca da bollo','77.47','decimal',1,'Fatturazione','2026-02-18 19:20:36','2026-02-18 19:21:06',NULL,0),(12,'Conto aziendale predefinito','','query=SELECT id,descrizi