INSERT INTO `zz_widgets` VALUES (1,'Numero di clienti','stats',2,'controller_top',NULL,'SELECT COUNT(an_anagrafiche.idanagrafica) AS dato FROM an_anagrafiche INNER JOIN (an_tipianagrafiche_anagrafiche INNER JOIN an_tipianagrafiche ON an_tipianagrafiche_anagrafiche.idtipoanagrafica=an_tipianagrafiche.id LEFT JOIN an_tipianagrafiche_lang ON (an_tipianagrafiche_lang.id_record = an_tipianagrafiche.id AND |lang|)) ON an_anagrafiche.idanagrafica=an_tipianagrafiche_anagrafiche.idanagrafica WHERE 1=1 AND name=\"Cliente\" AND `deleted_at` IS NULL HAVING 2=2','success','fa fa-user','','if($(\'#th_Tipo input\').val()!= \'Cliente\'){ $(\'#th_Tipo input\').val(\'Cliente\').trigger(\'keyup\');} else { $(\'#th_Tipo input\').val(\'\').trigger(\'keyup\');}','javascript','',1,0,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:03'),(2,'Numero di tecnici','stats',2,'controller_top',NULL,'SELECT COUNT(an_anagrafiche.idanagrafica) AS dato FROM an_anagrafiche INNER JOIN (an_tipianagrafiche_anagrafiche INNER JOIN an_tipianagrafiche ON an_tipianagrafiche_anagrafiche.idtipoanagrafica=an_tipianagrafiche.id LEFT JOIN an_tipianagrafiche_lang ON (an_tipianagrafiche_lang.id_record = an_tipianagrafiche.id AND |lang|)) ON an_anagrafiche.idanagrafica=an_tipianagrafiche_anagrafiche.idanagrafica WHERE 1=1 AND name=\"Tecnico\" AND `deleted_at` IS NULL HAVING 2=2','warning','fa fa-cog','','if($(\'#th_Tipo input\').val()!= \'Tecnico\'){ $(\'#th_Tipo input\').val(\'Tecnico\').trigger(\'keyup\');} else { $(\'#th_Tipo input\').val(\'\').trigger(\'keyup\');}','javascript','',1,1,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:03'),(3,'Numero di fornitori','stats',2,'controller_top',NULL,'SELECT COUNT(an_anagrafiche.idanagrafica) AS dato FROM an_anagrafiche INNER JOIN (an_tipianagrafiche_anagrafiche INNER JOIN an_tipianagrafiche ON an_tipianagrafiche_anagrafiche.idtipoanagrafica=an_tipianagrafiche.id LEFT JOIN an_tipianagrafiche_lang ON (an_tipianagrafiche_lang.id_record = an_tipianagrafiche.id AND |lang|)) ON an_anagrafiche.idanagrafica=an_tipianagrafiche_anagrafiche.idanagrafica WHERE 1=1 AND name=\"Fornitore\" AND `deleted_at` IS NULL HAVING 2=2','danger','fa fa-truck','','if($(\'#th_Tipo input\').val()!= \'Fornitore\'){ $(\'#th_Tipo input\').val(\'Fornitore\').trigger(\'keyup\');} else { $(\'#th_Tipo input\').val(\'\').trigger(\'keyup\');}','javascript','',1,3,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:03'),(4,'Numero di agenti','stats',2,'controller_top',NULL,'SELECT COUNT(an_anagrafiche.idanagrafica) AS dato FROM an_anagrafiche INNER JOIN (an_tipianagrafiche_anagrafiche INNER JOIN an_tipianagrafiche ON an_tipianagrafiche_anagrafiche.idtipoanagrafica=an_tipianagrafiche.id LEFT JOIN an_tipianagrafiche_lang ON (an_tipianagrafiche_lang.id_record = an_tipianagrafiche.id AND |lang|)) ON an_anagrafiche.idanagrafica=an_tipianagrafiche_anagrafiche.idanagrafica WHERE 1=1 AND name=\"Agente\" AND `deleted_at` IS NULL HAVING 2=2','maroon','fa fa-briefcase','','if($(\'#th_Tipo input\').val()!= \'Agente\'){ $(\'#th_Tipo input\').val(\'Agente\').trigger(\'keyup\');} else { $(\'#th_Tipo input\').val(\'\').trigger(\'keyup\');}','javascript','',1,3,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:03'),(5,'Promemoria contratti da pianificare','stats',1,'controller_top',NULL,'SELECT COUNT(id) AS dato FROM co_promemoria WHERE idcontratto IN( SELECT id FROM co_contratti WHERE idstato IN (SELECT id FROM co_staticontratti WHERE is_pianificabile = 1)) AND idintervento IS NULL','warning','fa fa-cog','','./plugins/pianificazione_interventi/widgets/promemoria_da_pianificare.php','popup','',1,0,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:00'),(7,'Scadenze','stats',1,'controller_top',NULL,'SELECT COUNT(co_documenti.id) AS dato FROM co_scadenziario INNER JOIN (((co_documenti INNER JOIN an_anagrafiche ON co_documenti.idanagrafica=an_anagrafiche.idanagrafica) INNER JOIN co_pagamenti ON co_documenti.idpagamento=co_pagamenti.id) INNER JOIN co_tipidocumento ON co_documenti.idtipodocumento=co_tipidocumento.id) ON co_scadenziario.iddocumento=co_documenti.id WHERE ABS(pagato) < ABS(da_pagare) AND scadenza >= \"|period_start|\" AND scadenza <= \"|period_end|\" ORDER BY scadenza ASC','danger','fa fa-money','','./controller.php?id_module=18','link','',1,2,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:00'),(8,'Articoli in esaurimento','stats',1,'controller_top',NULL,'SELECT COUNT(DISTINCT mg_articoli.id) AS dato FROM `mg_articoli`INNER JOIN `mg_scorte_sedi` ON `mg_scorte_sedi`.`id_articolo` = `mg_articoli`.`id`LEFT JOIN (SELECT IFNULL(SUM(qta), 0) AS tot, idarticolo, idsede FROM mg_movimenti GROUP BY idarticolo, idsede) movimenti ON movimenti.idsede = mg_scorte_sedi.id_sede AND movimenti.idarticolo = mg_articoli.id WHERE `mg_articoli`.`attivo` = 1 AND `mg_articoli`.`deleted_at` IS NULL AND `mg_scorte_sedi`.`threshold_qta` > 0 AND IFNULL(movimenti.tot, 0) < `mg_scorte_sedi`.`threshold_qta`','danger','fa fa-truck','','./modules/articoli/widgets/articoli.dashboard.php','popup','',1,3,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:53'),(9,'Preventivi in lavorazione','stats',1,'controller_top',NULL,'SELECT COUNT(co_preventivi.id) AS dato FROM co_preventivi INNER JOIN co_statipreventivi ON co_preventivi.idstato = co_statipreventivi.id LEFT JOIN co_statipreventivi_lang ON (co_statipreventivi_lang.id_record = co_statipreventivi.id AND co_statipreventivi_lang.id_lang = (SELECT valore FROM zz_settings WHERE nome = \"Lingua\")) WHERE name =\"In lavorazione\" AND default_revision=1','success','fa fa-tasks','','./modules/preventivi/widgets/preventivi.dashboard.php','popup','',1,4,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:00'),(10,'Contratti in scadenza','stats',1,'controller_top',NULL,'SELECT COUNT(`dati`.`id`) AS dato FROM (SELECT `co_contratti`.`id`,((SELECT SUM(`co_righe_contratti`.`qta`) FROM `co_righe_contratti` WHERE `co_righe_contratti`.`um` = \"ore\" AND `co_righe_contratti`.`idcontratto` = `co_contratti`.`id`) - IFNULL((SELECT SUM(`in_interventi_tecnici`.`ore`) FROM `in_interventi_tecnici` INNER JOIN `in_interventi` ON `in_interventi_tecnici`.`idintervento` = `in_interventi`.`id` WHERE `in_interventi`.`id_contratto` = `co_contratti`.`id` AND `in_interventi`.`idstatointervento` IN (SELECT `in_statiintervento`.`id` FROM `in_statiintervento` WHERE `in_statiintervento`.`is_bloccato` = 1)),0)) AS `ore_rimanenti`, DATEDIFF(`data_conclusione`, NOW()) AS giorni_rimanenti, `data_conclusione`, `ore_preavviso_rinnovo`, `giorni_preavviso_rinnovo`, (SELECT `ragione_sociale` FROM `an_anagrafiche` WHERE `idanagrafica` = `co_contratti`.`idanagrafica`) AS ragione_sociale FROM `co_contratti` INNER JOIN `co_staticontratti` ON `co_staticontratti`.`id` = `co_contratti`.`idstato` LEFT JOIN `co_staticontratti_lang` ON (`co_staticontratti`.`id` = `co_staticontratti_lang`.`id_record` AND `co_staticontratti_lang`.`id_lang` = (SELECT `valore` FROM `zz_settings` WHERE `nome` = \"Lingua\")) WHERE `rinnovabile` = 1 AND YEAR(`data_conclusione`) > 1970 AND `co_contratti`.`id` NOT IN (SELECT `idcontratto_prev` FROM `co_contratti` contratti) AND `co_staticontratti_lang`.`title` NOT IN (\"Concluso\", \"Rifiutato\", \"Bozza\") HAVING (`ore_rimanenti` <= `ore_preavviso_rinnovo` OR DATEDIFF(`data_conclusione`, NOW()) <= ABS(`giorni_preavviso_rinnovo`)) ORDER BY `giorni_rimanenti` ASC,`ore_rimanenti` ASC) dati','danger','fa fa-edit','','./modules/contratti/widgets/contratti_scadenza.dashboard.php','popup','',1,5,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:39'),(11,'Rate contrattuali','stats',1,'controller_top',NULL,'SELECT COUNT(id) AS dato FROM co_fatturazione_contratti WHERE idcontratto IN( SELECT id FROM co_contratti WHERE co_contratti.idstato IN (SELECT id FROM co_staticontratti WHERE is_fatturabile = 1)) AND co_fatturazione_contratti.iddocumento=0','info','fa fa-folder-open','','./plugins/pianificazione_fatturazione/widgets/rate_contrattuali.php','popup','',1,6,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:00'),(12,'Stampa inventario','print',21,'controller_top',NULL,'','info','fa fa-print','','./modules/articoli/widgets/stampa_inventario.php','popup','',1,1,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:00'),(13,'Fatturato','stats',14,'controller_top',NULL,'SELECT\n    CONCAT_WS(\' \', REPLACE(REPLACE(REPLACE(FORMAT((\n    SELECT SUM(\n    (`co_righe_documenti`.`subtotale` - `co_righe_documenti`.`sconto`) * IF(`co_tipidocumento`.`reversed`, -1, 1)\n    )\n    ), 2), \',\', \'#\'), \'.\', \',\'), \'#\', \'.\'), \'&euro;\') AS dato\nFROM \n    `co_righe_documenti`\n    INNER JOIN `co_documenti` ON `co_righe_documenti`.`iddocumento` = `co_documenti`.`id`\n    INNER JOIN `co_tipidocumento` ON `co_documenti`.`idtipodocumento` = `co_tipidocumento`.`id`\n    INNER JOIN `co_statidocumento` ON `co_documenti`.`idstatodocumento` = `co_statidocumento`.`id`\n    LEFT JOIN `co_statidocumento_lang` ON (`co_statidocumento`.`id` = `co_statidocumento_lang`.`id_record` AND `co_statidocumento_lang`.|lang|)\nWHERE \n    `co_statidocumento_lang`.`title`!=\'Bozza\' AND `co_tipidocumento`.`dir`=\'entrata\' |segment(`co_documenti`.`id_segment`)| AND `data` >= \'|period_start|\' AND `data` <= \'|period_end|\' AND 1=1','success','fa fa-money','','','','',1,1,'Fatturato IVA esclusa.','2026-02-18 19:20:36','2026-02-18 19:24:00'),(14,'Acquisti','stats',15,'controller_top',NULL,'SELECT\n CONCAT_WS(\' \', REPLACE(REPLACE(REPLACE(FORMAT((\n SELECT SUM(\n (co_righe_documenti.subtotale - co_righe_documenti.sconto) * IF(co_tipidocumento.reversed, -1, 1)\n )\n ), 2), \',\', \'#\'), \'.\', \',\'), \'#\', \'.\'), \'&euro;\') AS dato\nFROM co_righe_documenti\n INNER JOIN co_documenti ON co_righe_documenti.iddocumento = co_documenti.id\n INNER JOIN co_tipidocumento ON co_documenti.idtipodocumento = co_tipidocumento.id\nWHERE co_tipidocumento.dir=\'uscita\' |segment(`co_documenti`.`id_segment`)| AND data >= \'|period_start|\' AND data <= \'|period_end|\' AND 1=1','danger','fa fa-money','','','','',1,1,'Fatturato IVA esclusa.','2026-02-18 19:20:36','2026-02-18 19:24:00'),(15,'Crediti da clienti','stats',14,'controller_top',NULL,'SELECT \n CONCAT_WS(\' \', REPLACE(REPLACE(REPLACE(FORMAT((\n SELECT SUM(da_pagare-pagato)), 2), \',\', \'#\'), \'.\', \',\'),\'#\', \'.\'), \'&euro;\') AS dato FROM (co_scadenziario INNER JOIN co_documenti ON co_scadenziario.iddocumento=co_documenti.id) INNER JOIN co_tipidocumento ON co_documenti.idtipodocumento=co_tipidocumento.id WHERE co_tipidocumento.dir=\'entrata\' AND co_documenti.idstatodocumento!=1 |segment(`co_documenti`.`id_segment`)| AND 1=1','warning','fa fa-warning','','','','',1,2,'Crediti iva inclusa accumulati con i clienti durante tutti gli anni di attività.','2026-02-18 19:20:36','2026-02-18 19:24:00'),(16,'Debiti verso fornitori','stats',15,'controller_top',NULL,'SELECT CONCAT_WS(\' \', REPLACE(REPLACE(REPLACE(FORMAT((SELECT ABS(SUM(da_pagare-pagato))), 2), \',\', \'#\'), \'.\', \',\'),\'#\', \'.\'), \'&euro;\') AS dato FROM (co_scadenziario INNER JOIN co_documenti ON co_scadenziario.iddocumento=co_documenti.id) INNER JOIN co_tipidocumento ON co_documenti.idtipodocumento=co_tipidocumento.id WHERE co_tipidocumento.dir=\'uscita\' AND co_documenti.idstatodocumento!=1 |segment(`co_documenti`.`id_segment`)| AND 1=1','warning','fa fa-warning','','','','',1,2,'Debiti iva inclusa accumulati con i fornitori durante tutti gli anni di attività.','2026-02-18 19:20:36','2026-02-18 19:24:00'),(17,'Numero di vettori','stats',2,'controller_top',NULL,'SELECT COUNT(an_anagrafiche.idanagrafica) AS dato FROM an_anagrafiche INNER JOIN (an_tipianagrafiche_anagrafiche INNER JOIN an_tipianagrafiche ON an_tipianagrafiche_anagrafiche.idtipoanagrafica=an_tipianagrafiche.id LEFT JOIN an_tipianagrafiche_lang ON (an_tipianagrafiche_lang.id_record = an_tipianagrafiche.id AND |lang|)) ON an_anagrafiche.idanagrafica=an_tipianagrafiche_anagrafiche.idanagrafica WHERE 1=1 AND name=\"Vettore\" AND `deleted_at` IS NULL HAVING 2=2','info','fa fa-truck','','if($(\'#th_Tipo input\').val()!= \'Vettore\'){ $(\'#th_Tipo input\').val(\'Vettore\').trigger(\'keyup\');} else { $(\'#th_Tipo input\').val(\'\').trigger(\'keyup\');}','javascript','',1,4,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:03'),(18,'Tutte le anagrafiche','stats',2,'controller_top',NULL,'SELECT COUNT(an_anagrafiche.idanagrafica) AS dato FROM an_anagrafiche INNER JOIN (an_tipianagrafiche_anagrafiche INNER JOIN an_tipianagrafiche ON an_tipianagrafiche_anagrafiche.idtipoanagrafica=an_tipianagrafiche.id LEFT JOIN an_tipianagrafiche_lang ON (an_tipianagrafiche_lang.id_record = an_tipianagrafiche.id AND |lang|)) ON an_anagrafiche.idanagrafica=an_tipianagrafiche_anagrafiche.idanagrafica WHERE 1=1 AND `deleted_at` IS NULL HAVING 2=2','gray','fa fa-users','','$(\'#th_Tipo input\').val(\'\').trigger(\'keyup\');','javascript','',1,5,NULL,'2026-02-18 19:20:36','2026-02-18 19:24:03'),(20,'Valore magazzino','stats',21,'controller_top',NULL,'SELECT CONCAT_WS(\" \", REPLACE(REPLACE(REPLACE(FORMAT(SUM(prezzo_acquisto*qta),2), \",\", \"#\"), \".\", \",\"), \"#\", \".\"), \"&euro;\") AS dato FROM mg_articoli WHERE qta>0 AND deleted_at IS NULL AND servizio=0 AND 1=1','danger','fa fa-money','','','','',1,1,'Articoli a magazzino (tutti o solo attivi secondo il segmento)','2026-02-18 19:20:36','2026-02-18 19:24:00'),(21,'Articoli in magazzino','stats',21,'controller_top',NULL,'SELECT REPLACE(REPLACE(REPLACE(FORMAT(SUM(qta),2), \",\", \"#\"), \".\", \",\"), \"#\", \".\") AS dato FROM mg_articoli WHERE qta>0 AND deleted_at IS NULL AND servizio=0 AND 1=1','info','fa fa-check-square-o','','','','',1,1,'Articoli a magazzino (tutti o solo attivi secondo il segmento)','2026-02-18 19:20:36','2026-02-18 19:24:00'),(22,'Stampa calendario','print',1,'controller_top',NULL,NULL,'gray','fa fa-print','','./modules/dashboard/widgets/stampa_calendario.dashboard.php','popup','',1,7,NULL,'2026-02-18 19:20:41','2026-02-18 19:24:00'),(23,'Attività da pianificare','stats',1,'controller_top',NULL,'SELECT COUNT(id) AS dato FROM in_interventi WHERE id NOT IN (SELECT idintervento FROM in_interventi_tecnici) AND idstatointervento IN (SELECT id FROM in_statiintervento WHERE is_bloccato = 0) ','warning','fa fa-cogs','','./modules/interventi/widgets/interventi_da_pianificare.php','popup','',1,0,NULL,'2026-02-18 19:20:43','2026-02-18 19:24:39'),(24,'Attività nello stato da programmare','stats',1,'controller_top',NULL,'SELECT COUNT(id) AS dato FROM in_interventi WHERE in_interventi.idstatointervento = (SELECT in_statiintervento.id FROM in_statiintervento WHERE in_statiintervento.codice=\'TODO\') ORDER BY in_interventi.data_richiesta ASC','warning','fa fa-hourglass-half','','./modules/interventi/widgets/interventi_da_programmare.php','popup','',1,8,NULL,'2026-02-18 19:21:06','2026-02-18 19:24:00'),(25,'Attività confermate','stats',1,'controller_top',NULL,'SELECT COUNT(id) AS dato FROM in_interventi WHERE in_interventi.idstatointervento = (SELECT in_statiintervento.id FROM in_statiintervento WHERE in_statiintervento.codice=\'WIP\') ORDER BY in_interventi.data_richiesta ASC','success','fa fa-hourglass-half','','./modules/interventi/widgets/interventi_confermati.php','popup','',1,8,NULL,'2026-02-18 19:21:06','2026-02-18 19:24:00'),(26,'Spazio utilizzato','chart',68,'controller_right','col-md-6',NULL,'success','fa fa-hdd-o','','',NULL,'./modules/stato_servizi/widgets/spazio_utilizzato.php',1,1,NULL,'2026-02-18 19:21:06','2026-02-18 19:24:08'),(27,'Note interne','custom',1,'controller_top',NULL,NULL,'info','fa fa-file-text-o ','','./modules/dashboard/widgets/notifiche.php','popup','./modules/dashboard/widgets/notifiche.php',1,1,NULL,'2026-02-18 19:21:15','2026-02-18 19:24:00'),(28,'Sincronizzazione disiscritti','custom',73,'controller_top',NULL,NULL,'success','fa fa-envelope ','','./modules/liste_newsletter/widgets/opt-out.php','popup','./modules/liste_newsletter/widgets/opt-out.php',0,1,NULL,'2026-02-18 19:22:17','2026-02-18 19:24:00'),(29,'Listini attivi','stats',88,'controller_top',NULL,'SELECT COUNT(mg_listini.id) AS dato FROM mg_listini WHERE 1=1 AND attivo=1 HAVING 2=2','success','fa fa-check','','','javascript','',1,1,NULL,'2026-02-18 19:22:49','2026-02-18 19:24:00'),(30,'Listini scaduti','stats',88,'controller_top',NULL,'SELECT COUNT(mg_listini.id) AS dato FROM mg_listini WHERE 1=1 AND attivo=0 HAVING 2=2','danger','fa fa-times','','','javascript','',1,2,NULL,'2026-02-18 19:22:49','2026-02-18 19:24:00'),(31,'Stampa calendario settimanale','print',1,'controller_top',NULL,NULL,'gray','fa fa-print','','./modules/dashboard/widgets/stampa_calendario_settimanale.dashboard.php','popup','',1,7,NULL,'2026-02-18 19:23:04','2026-02-18 19:24:00'),(32,'Preventivi da fatturare','stats',1,'controller_top',NULL,'SELECT COUNT(id) AS dato FROM co_preventivi WHERE idstato IN (SELECT id FROM co_statipreventivi WHERE is_fatturabile=1) AND default_revision=1','maroon','fa fa-file','','./modules/preventivi/widgets/preventivi.fatturare.dashboard.php','popup','',0,NULL,NULL,'2026-02-18 19:23:10','2026-02-18 19:24:00'),(33,'Stampa carico odierno','print',92,'controller_top','col-md-4','','success','fa fa-print','','var data_carico = prompt(\'Data del carico da stampare?\', moment(new Date()).format(\'DD/MM/YYYY\'));\r\nif ( data_carico != null){ \r\nwindow.open(\'pdfgen.php?id_print=54&search_targa=\'+$(\'#th_Targa input\').val()+\'&search_nome=\'+$(\'#th_Nome input\').val()+\'&data_carico=\'+data_carico); \r\n}','javascript','',1,2,NULL,'2026-02-18 19:23:17','2026-02-18 19:24:00'),(34,'Stampa giacenza','print',92,'controller_top','col-md-4','','info','fa fa-truck','','if( confirm(\'Stampare la giacenza attuale sugli automezzi?\') ){ window.open(\'pdfgen.php?id_print=53&search_targa=\'+$(\'#th_Targa input\').val()+\'&search_nome=\'+$(\'#th_Nome input\').val()); }','javascript','',1,1,NULL,'2026-02-18 19:23:17','2026-02-18 19:24:00'),(35,'Stampa cespiti','print',21,'controller_top','col-md-3','','info','fa fa-print','','./modules/articoli/widgets/stampa_cespiti.php','popup','',1,1,NULL,'2026-02-18 19:23:33','2026-02-18 19:24:00');
